$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec('CREATE TABLE ws_records(kind TEXT,id TEXT,payload TEXT);');Growth::migrate($db);
$config=['site'=>['url'=>'https://catalog.example.org/sub','indexing'=>true],'seo'=>SEOSettings::defaults(['site'=>['indexing'=>true]])];$repo=new Repository($db,$config);$service=new Growth($db,$repo,$config);
$base=['locale'=>'en','revision'=>1,'status'=>'published','seoApproved'=>true,'summary'=>'Synthetic review fixture','topic'=>'','intent'=>'','authorId'=>'','appIds'=>[],'sections'=>[['heading'=>'Evidence','paragraphs'=>['Synthetic fixture text.']]],'sources'=>[['title'=>'Official','url'=>'https://example.org','checkedAt'=>'2026-01-01']],'links'=>[],'seo'=>['noindex'=>false],'test'=>null,'reviewNote'=>'Private review note','updatedAt'=>'2026-01-01T00:00:00Z','sourceFingerprints'=>[]];
foreach([['id'=>'author','kind'=>'author','title'=>'Fixture Author'],['id'=>'related','kind'=>'intent','title'=>'Related resource'],['id'=>'unrelated','kind'=>'intent','title'=>'Unrelated resource'],['id'=>'hidden','kind'=>'intent','title'=>'Private draft','status'=>'draft'],['id'=>'offline-locale','kind'=>'intent','title'=>'Unavailable package','locale'=>'de'],['id'=>'main','kind'=>'intent','title'=>'Main resource','authorId'=>'author','links'=>[['kind'=>'growth','id'=>'related','label'=>'Read related resource'],['kind'=>'growth','id'=>'hidden','label'=>'Draft must stay hidden']]],['id'=>'main','kind'=>'intent','title'=>'Türkçe ana kaynak','locale'=>'tr']] as $patch){$d=array_replace($base,$patch,['slug'=>$patch['id']]);$db->prepare('INSERT INTO ws_growth_documents(id,locale,kind,slug,revision,payload) VALUES(?,?,?,?,?,?)')->execute([$d['id'],$d['locale'],$d['kind'],$d['slug'],1,json_encode($d)]);}
